-- Migration 0047 — Seed des Default-Agenten „Builder" fuer Bestands-Workspaces
--
-- Spiegelt `_seed_default_agents` (+ den 'agent-builder'-Template-Eintrag in
-- `_DEFAULT_TEMPLATES`) aus workspace_repository.py ueber ALLE bestehenden
-- Workspaces. Inhaltlich re-targeted auf die Who2Be-MCP-Write-Tools (kein
-- externer Store). Beide Schichten synchron halten (bekannte Drift-Quelle, vgl. 0023b).
--
-- Reihenfolge wegen der Composite-FKs (agent -> persona, agent -> template):
--   1. Template 'agent-builder' (falls 0023b/Seed es noch nicht hat)
--   2. Persona „Builder" + persona_version v1 (active)
--   3. 4 Playbooks + playbook_version v1 (active)
--   4. persona_playbook-Links (Persona <-> 4 Playbooks)
--   5. agent-Row (write-faehige tool_policy, status 'enabled')
--
-- Vollstaendig idempotent: Template via ON CONFLICT (workspace_id, slug);
-- Persona/Playbook/Agent via NOT EXISTS (workspace_id + name); Versions-Inserts
-- via NOT EXISTS; Links via ON CONFLICT DO NOTHING. owner_id: erster Admin des
-- Workspaces (CTE-Pickup, wie 0023b).

-- 1) Template 'agent-builder' -------------------------------------------------
WITH ws_owner AS (
    SELECT w.id AS workspace_id,
           COALESCE(
             (SELECT user_id FROM workspace_member
                WHERE workspace_id = w.id AND role = 'admin'
                ORDER BY joined_at ASC, user_id ASC LIMIT 1),
             (SELECT user_id FROM workspace_member
                WHERE workspace_id = w.id
                ORDER BY joined_at ASC, user_id ASC LIMIT 1)
           ) AS owner_id
      FROM workspace w
),
inserted_template AS (
    INSERT INTO system_prompt_template (workspace_id, owner_id, name, slug)
    SELECT wo.workspace_id, wo.owner_id, 'Agent-Builder', 'agent-builder'
      FROM ws_owner wo
     WHERE wo.owner_id IS NOT NULL
    ON CONFLICT (workspace_id, slug) DO NOTHING
    RETURNING id, owner_id
)
INSERT INTO system_prompt_template_version
       (template_id, version, content, status, created_by)
SELECT it.id, 1, $w2btpl${"description": "", "body": "[\n  {\n    \"id\": \"ab-h1\",\n    \"type\": \"heading\",\n    \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"},\n    \"content\": [{\"type\": \"text\", \"text\": \"Rolle\", \"styles\": {}}],\n    \"children\": []\n  },\n  {\n    \"id\": \"ab-p1\",\n    \"type\": \"paragraph\",\n    \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"},\n    \"content\": [\n      {\"type\": \"text\", \"text\": \"Du bist \", \"styles\": {}},\n      {\"type\": \"placeholder\", \"props\": {\"kind\": \"persona-field\", \"target_id\": \"name\", \"label\": \"Persona: Name\"}},\n      {\"type\": \"text\", \"text\": \" — \", \"styles\": {}},\n      {\"type\": \"placeholder\", \"props\": {\"kind\": \"persona-field\", \"target_id\": \"description\", \"label\": \"Persona: Beschreibung\"}},\n      {\"type\": \"text\", \"text\": \". Du bist der Architektur-Partner, der gemeinsam mit dem Nutzer neue Agents baut: Personas, Playbooks, Resources und die Agent-Konfiguration selbst. Heute ist der \", \"styles\": {}},\n      {\"type\": \"placeholder\", \"props\": {\"kind\": \"date\", \"target_id\": \"human\", \"label\": \"Datum\"}},\n      {\"type\": \"text\", \"text\": \".\", \"styles\": {}}\n    ],\n    \"children\": []\n  },\n  {\n    \"id\": \"ab-h2\",\n    \"type\": \"heading\",\n    \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"},\n    \"content\": [{\"type\": \"text\", \"text\": \"Hintergrund zur Rolle\", \"styles\": {}}],\n    \"children\": []\n  },\n  {\n    \"id\": \"ab-p2\",\n    \"type\": \"paragraph\",\n    \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"},\n    \"content\": [\n      {\"type\": \"placeholder\", \"props\": {\"kind\": \"persona-field\", \"target_id\": \"profile\", \"label\": \"Persona: 