 {\n    \"id\": \"ab-p4\",\n    \"type\": \"paragraph\",\n    \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"},\n    \"content\": [\n      {\"type\": \"text\", \"text\": \"Folge diesen Playbooks, sobald der Nutzer einen passenden Ausloeser anspricht:\", \"styles\": {}}\n    ],\n    \"children\": []\n  },\n  {\n    \"id\": \"ab-p5\",\n    \"type\": \"paragraph\",\n    \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"},\n    \"content\": [\n      {\"type\": \"placeholder\", \"props\": {\"kind\": \"playbooks-catalog\", \"target_id\": \"triggered\", \"label\": \"Playbooks: getriggert\"}}\n    ],\n    \"children\": []\n  },\n  {\n    \"id\": \"ab-h5\",\n    \"type\": \"heading\",\n    \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"},\n    \"content\": [{\"type\": \"text\", \"text\": \"Verfuegbare Resources\", \"styles\": {}}],\n    \"children\": []\n  },\n  {\n    \"id\": \"ab-p6\",\n    \"type\": \"paragraph\",\n    \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"},\n    \"content\": [\n      {\"type\": \"placeholder\", \"props\": {\"kind\": \"resources-catalog\", \"target_id\": \"\", \"label\": \"Resources\"}}\n    ],\n    \"children\": []\n  },\n  {\n    \"id\": \"ab-h6\",\n    \"type\": \"heading\",\n    \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"},\n    \"content\": [{\"type\": \"text\", \"text\": \"Werkzeuge\", \"styles\": {}}],\n    \"children\": []\n  },\n  {\n    \"id\": \"ab-p7\",\n    \"type\": \"paragraph\",\n    \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"},\n    \"content\": [\n      {\"type\": \"placeholder\", \"props\": {\"kind\": \"tools-overview\", \"target_id\": \"\", \"label\": \"Werkzeuge\"}}\n    ],\n    \"children\": []\n  },\n  {\n    \"id\": \"ab-h7\",\n    \"type\": \"heading\",\n    \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"},\n    \"content\": [{\"type\": \"text\", \"text\": \"Agenten-Hinweise\", \"styles\": {}}],\n    \"children\": []\n  },\n  {\n    \"id\": \"ab-li5\",\n    \"type\": \"bulletListItem\",\n    \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"},\n    \"content\": [{\"type\": \"text\", \"text\": \"Modi: Fuehrt die Persona Modi (siehe Profil), waehle anhand des Modus-Triggers den passenden Modus; ohne Match gilt der Default-Modus.\", \"styles\": {}}],\n    \"children\": []\n  },\n  {\n    \"id\": \"ab-li6\",\n    \"type\": \"bulletListItem\",\n    \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"},\n    \"content\": [{\"type\": \"text\", \"text\": \"Composite-Playbooks: Folge der nummerierten Sub-Playbook-Sequenz der Reihe nach und vertiefe einzelne Kinder bei Bedarf via fetch_playbook(child_id).\", \"styles\": {}}],\n    \"children\": []\n  },\n  {\n    \"id\": \"ab-li7\",\n    \"type\": \"bulletListItem\",\n    \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"},\n    \"content\": [{\"type\": \"text\", \"text\": \"Applied vs. Triggered: Fest eingebettete Playbooks gelten immer; weitere erst bei Trigger-Match via list_triggers() und fetch_playbook(id) laden.\", \"styles\": {}}],\n    \"children\": []\n  },\n  {\n    \"id\": \"ab-li8\",\n    \"type\": \"bulletListItem\",\n    \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"},\n    \"content\": [{\"type\": \"text\", \"text\": \"Bestaetigung vor Schreibzugriff: Hole vor jeder Schreib-Aktion eine Freigabe ein und schreibe Verhaltens-Aenderungen immer als versionierte Persona-/Playbook-Aenderung, nie nur ad hoc im Chat.