-- 2) Persona „Builder" --------------------------------------------------------
WITH ws_owner AS (
    SELECT w.id AS workspace_id,
           COALESCE(
             (SELECT user_id FROM workspace_member
                WHERE workspace_id = w.id AND role = 'admin'
                ORDER BY joined_at ASC, user_id ASC LIMIT 1),
             (SELECT user_id FROM workspace_member
                WHERE workspace_id = w.id
                ORDER BY joined_at ASC, user_id ASC LIMIT 1)
           ) AS owner_id
      FROM workspace w
),
inserted_persona AS (
    INSERT INTO persona (workspace_id, owner_id, name)
    SELECT wo.workspace_id, wo.owner_id, 'Builder'
      FROM ws_owner wo
     WHERE wo.owner_id IS NOT NULL
       AND NOT EXISTS (
         SELECT 1 FROM persona p
          WHERE p.workspace_id = wo.workspace_id AND p.name = 'Builder'
       )
    RETURNING id, owner_id
)
