-- 3.1) Playbook Persona anlegen & pflegen ---------------------------------------------------
WITH ws_owner AS (
    SELECT w.id AS workspace_id,
           COALESCE(
             (SELECT user_id FROM workspace_member
                WHERE workspace_id = w.id AND role = 'admin'
                ORDER BY joined_at ASC, user_id ASC LIMIT 1),
             (SELECT user_id FROM workspace_member
                WHERE workspace_id = w.id
                ORDER BY joined_at ASC, user_id ASC LIMIT 1)
           ) AS owner_id
      FROM workspace w
),
inserted_playbook AS (
    INSERT INTO playbook (workspace_id, owner_id, name, type, tags, triggers)
    SELECT wo.workspace_id, wo.owner_id, 'Persona anlegen & pflegen', 'workflow',
           ARRAY['persona', 'crud', 'agent-building']::text[], 'persona anlegen, persona bearbeiten, persona pflegen, neue persona'
      FROM ws_owner wo
     WHERE wo.owner_id IS NOT NULL
       AND NOT EXISTS (
         SELECT 1 FROM playbook p
          WHERE p.workspace_id = wo.workspace_id AND p.name = 'Persona anlegen & pflegen'
       )
    RETURNING id, owner_id
)
INSERT INTO playbook_version (playbook_id, version, content, status, created_by, locale)
SELECT ipb.id, 1, $w2bpb1${"description": "Eine Persona via MCP-Write-Tools anlegen, als Draft aendern und nach active schalten.", "body": "[{\"id\": \"pb-persona-h-zweck\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Zweck\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-p-zweck\", \"type\": \"paragraph\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"CRUD-Workflow fuer Personas in Who2Be: eine Persona anlegen, pflegen oder zurueckziehen — mit Schema-Disziplin und Phasen-Trennung (Verstehen → Vorschlag → Schreiben → Hand-Off). Drei Modi: Create (neue Persona), Update (bestehende aendern), Retire (deaktivieren). Geschrieben wird ausschliesslich ueber die Who2Be-MCP-Write-Tools; der Draft→active-Workflow bleibt serverseitig.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-h-trigger\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Trigger-Stichworte\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-p-trigger\", \"type\": \"paragraph\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"neue Persona; neuer Agent; Persona anlegen; Persona bearbeiten; Persona editieren; Persona aendern; Persona zurueckziehen; Persona deaktivieren; Persona retiren.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-h-prozedur\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Prozedur\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-p-modus\", \"type\": \"paragraph\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Erkenne zuerst den Modus: Create, wenn der Nutzer einen Agenten/Persona-Namen nennt, der noch nicht existiert; Update, wenn er eine bestehende Persona plus Aenderungswunsch nennt; Retire, wenn er eine Persona deaktivieren will. Bei Mehrdeutigkeit zuerst get_persona(identifier) lesen und klar nachfragen, welche Persona gemeint ist.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-li-1\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Create — Verstehen: Klaerungsfragen phasenweise, 1-2 pro Turn, nie alle auf einmal. Identity (eine knappe Zeile), Tone & Style (mit Beispiel-Phrasen), Allowed (4-6 konkrete Capabilities), Forbidden (Domaen-Grenzen + Anti-Patterns), Output Style (Form, Laenge), Modi-Entscheidung (Single-Mode ist Standard; Multi-Mode nur bei fundamental anderer Stimme/Output).\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-li-2\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Create — Vorschlag: Persona-Body konsolidieren (description + BlockNote-Profil mit Identity, Tone & Style, Allowed, Forbidden, Output Style; optional modes). Dem Nutzer zeigen, Trade-offs erklaeren, Bestaetigung einholen.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-li-3\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Create — Schreiben: create_persona(name, content, locale='de') aufrufen. Die neue Version 1 entsteht serverseitig als status='draft' — nie direkt aktiv. traits und tags fuer Stimme bzw. Domaene setzen.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-li-4\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Update — Verstehen & Vorschlag: get_persona(identifier) lesen, betroffene Sektion (Identity / Tone & Style / Allowed / Forbidden / Output Style / Modi) zeigen, Aenderungswunsch klaeren, Edit-Vorschlag konsolidieren und bestaetigen lassen.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-li-5\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Update — Schreiben: update_persona(persona_id, content) legt automatisch einen neuen Draft an (PUT auf eine aktive Version erzeugt einen Draft; existiert bereits ein Draft, kommt 409). Aenderungen sammeln, nicht pro Mikro-Edit eine neue Version erzwingen.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-li-6\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Verknuepfungen: Welche Playbooks die Persona fuehren soll, via set_persona_playbooks(persona_id, playbook_ids) setzen (Replace-Semantik — die Liste ersetzt den Stand vollstaendig). Vorher mit list_playbooks() die passenden IDs ermitteln.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-li-7\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Aktivieren: Sobald der Nutzer freigibt, transition_persona(persona_id, version, to='active') aufrufen — promoten ist admin-gated und liegt beim Nutzer. Niemals beim Anlegen automatisch aktivieren.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-li-8\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Retire: get_persona(identifier) lesen; pruefen, ob Agenten diese Persona nutzen, und den Nutzer warnen. Dann transition_persona(persona_id, version, to='inactive') aufrufen. restore_persona(persona_id, version) stellt eine fruehere Version als neuen Draft wieder her, falls ein Rollback noetig ist.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-h-tools\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Tools & Operations\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-li-t1\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"create_persona — neue Persona als Draft-Version 1 anlegen.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-li-t2\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"update_persona — Inhalt einer Persona als neuen Draft aendern.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-li-t3\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"transition_persona — eine Version schalten (draft/review benoetigt persona_write; active/inactive benoetigt promote_retire).\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-li-t4\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"restore_persona — eine fruehere Version als neuen Draft wiederherstellen.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-li-t5\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"set_persona_playbooks — die einer Persona zugeordneten Playbooks setzen (Replace-Semantik).\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-li-t6\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Reads: get_persona, list_playbooks zur Vorbereitung. Verboten: Status beim Anlegen direkt auf active setzen, sowie Schreiben in fremde Aggregate ueber dieses Playbook hinaus.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-h-handoff\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Hand-Off\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-li-ho1\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Persona-Inhalt vom Nutzer reviewen lassen und auf 'active' schalten, sobald freigegeben.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-li-ho2\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Passende Playbooks anlegen (Playbook-anlegen-Playbook) und via set_persona_playbooks verknuepfen.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-li-ho3\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Einen Agenten anlegen, der diese Persona plus ein Systemprompt-Template fuehrt (Agent-anlegen-Playbook).\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-persona-li-ho4\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Bei verhaltensrelevanten Updates: laufende Sitzungen halten den alten Stand gecached — fuer die neue Stimme einen neuen Chat starten. Bei Themen ausserhalb der Persona-Pflege hoeflich an die zustaendige Stelle rueckverweisen.\", \"styles\": {}}], \"children\": []}]", "type": "workflow", "tags": ["persona", "crud", "agent-building"], "triggers": "persona anlegen, persona bearbeiten, persona pflegen, neue persona"}$w2bpb1$::jsonb, 'active', ipb.owner_id, 'de'
  FROM inserted_playbook ipb
 WHERE NOT EXISTS (
       SELECT 1 FROM playbook_version v WHERE v.playbook_id = ipb.id AND v.version = 1
 );

-- 3.2) Playbook Playbook anlegen & pflegen ---------------------------------------------------
WITH ws_owner AS (
    SELECT w.id AS workspace_id,
           COALESCE(
             (SELECT user_id FROM workspace_member
                WHERE workspace_id = w.id AND role = 'admin'
                ORDER BY joined_at ASC, user_id ASC LIMIT 1),
             (SELECT user_id FROM workspace_member
                WHERE workspace_id = w.id
                ORDER BY joined_at ASC, user_id ASC LIMIT 1)
           ) AS owner_id
      FROM workspace w
),
inserted_playbook AS (
    INSERT INTO playbook (workspace_id, owner_id, name, type, tags, triggers)
    SELECT wo.workspace_id, wo.owner_id, 'Playbook anlegen & pflegen', 'workflow',
           ARRAY['playbook', 'crud', 'agent-building']::text[], 'playbook anlegen, playbook bearbeiten, composite, neues playbook'
      FROM ws_owner wo
     WHERE wo.owner_id IS NOT NULL
       AND NOT EXISTS (
         SELECT 1 FROM playbook p
          WHERE p.workspace_id = wo.workspace_id AND p.name = 'Playbook anlegen & pflegen'
       )
    RETURNING id, owner_id
)
INSERT INTO playbook_version (playbook_id, version, content, status, created_by, locale)
SELECT ipb.id, 1, $w2bpb2${"description": "Playbooks anlegen und pflegen — inkl. Resource-Verweisen und Composite-Sequenzen.", "body": "[{\"id\": \"pb-playbook-h-zweck\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Zweck\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-p-zweck\", \"type\": \"paragraph\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"CRUD-Workflow fuer Playbooks ueber die Who2Be-MCP-Write-Tools. Behandelt atomare und Composite-Playbooks. Ein Playbook wird als Draft angelegt und erst nach Review aktiviert — der Draft-zu-active-Workflow bleibt serverseitig. Die Sub-Playbook-Sequenz eines Composite wird ueber \", \"styles\": {}}, {\"type\": \"text\", \"text\": \"set_playbook_composes\", \"styles\": {\"code\": true}}, {\"type\": \"text\", \"text\": \" gesetzt; Verweise auf Wissens-Resources ueber \", \"styles\": {}}, {\"type\": \"text\", \"text\": \"set_playbook_resource_links\", \"styles\": {\"code\": true}}, {\"type\": \"text\", \"text\": \".\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-h-modus\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Modus erkennen\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-modus-create\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Create: Der User will einen neuen Workflow anlegen.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-modus-update\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Update: Der User nennt ein bestehendes Playbook plus eine Aenderung.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-modus-transition\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Transition: Ein Draft soll veroeffentlicht (active) oder ein aktives Playbook zurueckgezogen (inactive) werden.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-modus-restore\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Restore: Eine fruehere Version soll als neuer Draft wiederhergestellt werden.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-h-create\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Create — neues Playbook anlegen\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-h-create-p1\", \"type\": \"heading\", \"props\": {\"level\": 3, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Phase 1 — Verstehen\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-create-p1-persona\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Persona-Bindung: Welche Persona nutzt das Playbook? Existiert sie schon (get_persona)? Falls nein, zuerst dem Persona-Playbook folgen und die Persona anlegen, dann hierhin zurueckkehren.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-create-p1-type\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Type: Ist das Playbook atomar (eigenstaendiger Workflow, Leaf-Knoten) oder ein Composite (orchestriert mehrere atomare Playbooks in einer Sequenz)?\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-create-p1-triggers\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Triggers: Welche User-Phrasen aktivieren das Playbook? Semikolon-getrennt, mit [Platzhaltern] wo flexibel. Mit list_triggers() pruefen, ob ein Trigger schon belegt ist (Kollision vermeiden).\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-create-p1-tags\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Tags: Eine bestehende Kategorie nutzen oder ist es wirklich eine neue? Tags ueber list_playbooks() gegenpruefen, nicht wild erweitern.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-create-p1-desc\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Description: Eine praegnante 1-Zeilen-Zusammenfassung.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-create-p1-resources\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Resource-Verweise: Stuetzt sich das Playbook auf Wissens-Resources? Wenn ja, die Resource-IDs notieren (spaeter set_playbook_resource_links).\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-create-p1-composite\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Bei Composite: keine eigenen Schritte erfinden — der Body beschreibt nur die Orchestrierung; die fachlichen Schritte liegen in den Sub-Playbooks. Composite hat erst ab zwei Sub-Playbooks Wert.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-h-create-p2\", \"type\": \"heading\", \"props\": {\"level\": 3, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Phase 2 — Vorschlag\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-create-p2-atomic\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Atomic: Body als BlockNote-Dokument entwerfen — klare Phasen oder nummerierte Schritte, dazu die Sektionen Tools & Operations, Anti-Patterns und Notes.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-create-p2-composite\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Composite: Body als nummerierte Sequenz der Sub-Playbooks plus einen Sequenz-Disziplin-Abschnitt (wann passt das Composite nicht, was passiert wenn ein Sub-Playbook fehlt). Die Reihenfolge im Body ist die verbindliche Wahrheit.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-h-create-p3\", \"type\": \"heading\", \"props\": {\"level\": 3, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Phase 3 — Schreiben\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-create-p3-create\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"create_playbook\", \"styles\": {\"code\": true}}, {\"type\": \"text\", \"text\": \" mit name und content (description, body als BlockNote-JSON, type, tags, triggers) aufrufen. Das legt eine Draft-Version 1 an — Status ist serverseitig draft, nicht active.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-create-p3-composes\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Bei Composite: \", \"styles\": {}}, {\"type\": \"text\", \"text\": \"set_playbook_composes\", \"styles\": {\"code\": true}}, {\"type\": \"text\", \"text\": \" mit der parent-ID und den child-IDs in der gewuenschten Reihenfolge (Replace-Semantik). Nur aktive Sub-Playbooks verlinken.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-create-p3-resources\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Bei Resource-Verweisen: \", \"styles\": {}}, {\"type\": \"text\", \"text\": \"set_playbook_resource_links\", \"styles\": {\"code\": true}}, {\"type\": \"text\", \"text\": \" mit den Resource-Verknuepfungen setzen (Replace-Semantik).\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-create-p3-persona\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Persona-Bindung: Die M:M-Zuordnung Persona zu Playbook wird auf der Persona-Seite gesetzt (\", \"styles\": {}}, {\"type\": \"text\", \"text\": \"set_persona_playbooks\", \"styles\": {\"code\": true}}, {\"type\": \"text\", \"text\": \") — siehe Persona-Playbook. Ein Playbook ohne Persona haengt im Vakuum.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-h-create-p4\", \"type\": \"heading\", \"props\": {\"level\": 3, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Phase 4 — Hand-Off\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-create-p4-review\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Den Playbook-Inhalt mit dem User reviewen.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-create-p4-activate\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Nach Freigabe \", \"styles\": {}}, {\"type\": \"text\", \"text\": \"transition_playbook\", \"styles\": {\"code\": true}}, {\"type\": \"text\", \"text\": \" mit version=1 und to=\\\"active\\\" aufrufen. Das Promoten nach active braucht die Capability promote_retire.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-create-p4-composite-check\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Bei Composite: pruefen, dass alle verlinkten Sub-Playbooks existieren und auf active stehen — sonst werden inaktive Kinder beim Render uebersprungen.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-h-update\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Update — bestehendes Playbook aendern\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-update-1\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Verstehen: Das Playbook mit \", \"styles\": {}}, {\"type\": \"text\", \"text\": \"fetch_playbook\", \"styles\": {\"code\": true}}, {\"type\": \"text\", \"text\": \" laden, den Aenderungs-Bereich klaeren — Body-Sektion (Procedure / Tools & Operations / Anti-Patterns / Notes) oder ein Feld (triggers, tags, description, type).\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-update-2\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Vorschlag: Den Edit konsolidieren und mit dem User abstimmen, bevor geschrieben wird.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-update-3\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Schreiben: \", \"styles\": {}}, {\"type\": \"text\", \"text\": \"update_playbook\", \"styles\": {\"code\": true}}, {\"type\": \"text\", \"text\": \" mit dem vollstaendigen content aufrufen. Auf einer aktiven Version erzeugt das eine neue Draft-Version (kein In-Place-Edit; existiert schon ein Draft, kommt 409). Composes oder Resource-Links bei Bedarf mit set_playbook_composes / set_playbook_resource_links nachziehen.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-update-4\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Hand-Off: Den neuen Draft via transition_playbook auf active schalten. Bei Trigger-Aenderungen pruefen, ob ein Persona-Modus-Trigger auf den alten Wert verweist. Bei Type-Wechsel atomar zu Composite die Composes-Sequenz setzen, bei Composite zu atomar leeren.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-h-transition\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Transition — veroeffentlichen & zurueckziehen\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-transition-flow\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"transition_playbook\", \"styles\": {\"code\": true}}, {\"type\": \"text\", \"text\": \" mit id, version und to schaltet den Status: draft zu review, review zu active oder active zu inactive (zurueckgezogen). Nach draft/review genuegt die Schreib-Capability; Promote nach active und Retire nach inactive brauchen promote_retire.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-transition-backlinks\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Vor dem Zurueckziehen die eingehenden Referenzen pruefen: Welche Composites oder Personas nutzen das Playbook? Betroffene Stellen brauchen eine Anpassung — den User warnen.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-transition-invariant\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Status-Invariante: je Playbook ist hoechstens eine Version active. Eine neue Version zu aktivieren setzt die alte automatisch auf inactive.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-h-restore\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Restore — fruehere Version wiederherstellen\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-restore-1\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"restore_playbook\", \"styles\": {\"code\": true}}, {\"type\": \"text\", \"text\": \" mit id und der Quell-Version kopiert deren Inhalt als neuen Draft. Danach reviewen und ueber transition_playbook nach active schalten — kein direktes Ueberschreiben der aktiven Version.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-h-tools\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Tools & Operations\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-tools-read\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Read: fetch_playbook (Body + Felder), list_playbooks (Katalog, Tags), list_triggers (Trigger-Kollisionen pruefen).\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-tools-write\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Write: create_playbook (Draft-v1), update_playbook (neuer Draft), transition_playbook (Status schalten), restore_playbook (alte Version als Draft).\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-tools-link\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Verknuepfung: set_playbook_composes (Sub-Playbook-Sequenz eines Composite, Replace-Semantik), set_playbook_resource_links (Resource-Verweise, Replace-Semantik).\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-tools-forbidden\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Verboten: kein Hard-Delete ueber MCP; Composes nie auf draft- oder inactive-Playbooks setzen; kein Composite mit nur einem Sub-Playbook (Premature Composite); Personas oder Resources nicht in diesem Playbook editieren — dafuer gibt es eigene Playbooks.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-h-anti\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Anti-Patterns\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-anti-seq\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Composite ohne expliziten Sequenz-Disziplin-Abschnitt anlegen — wann es nicht passt und was bei fehlendem Sub-Playbook gilt, muss im Body stehen.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-anti-inactive\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Composes auf nicht-existierende oder nicht-aktive Playbooks setzen — ein Composite ist nur sinnvoll, wenn alle Sub-Playbooks einsatzbereit (active) sind.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-anti-persona\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Persona-Bindung vergessen — ein Playbook ohne zugeordnete Persona wird von keinem Agenten gefunden.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-anti-triggers\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Triggers ohne Semikolon-Trennung oder ohne [Platzhalter] wo flexibel — Konvention: Trigger-Phrase A; Trigger-Phrase B; Trigger fuer [X].\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-anti-activate\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Direkt auf active anlegen wollen — create_playbook erzeugt immer einen Draft; Aktivierung laeuft ausschliesslich ueber transition_playbook.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-anti-loose\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Procedure-Body als loses Stueck Fliesstext — nummerierte Schritte oder klare Phasen-Header nutzen.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-h-notes\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Notes\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-notes-composite\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Composite-Konvention: Die Reihenfolge in set_playbook_composes ist die ausfuehrungs-relevante Wahrheit. Beim Render eines Composite wird die nummerierte Sub-Playbook-Sequenz automatisch an den Body angehaengt; inaktive oder fehlende Kinder werden uebersprungen.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-playbook-notes-draft\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Der Draft-zu-active-Workflow bleibt serverseitig: MCP-Write-Tools legen nur Drafts an; die Veroeffentlichung laeuft immer ueber transition_playbook. Ein Hard-Delete gibt es ueber MCP bewusst nicht.\", \"styles\": {}}], \"children\": []}]", "type": "workflow", "tags": ["playbook", "crud", "agent-building"], "triggers": "playbook anlegen, playbook bearbeiten, composite, neues playbook"}$w2bpb2$::jsonb, 'active', ipb.owner_id, 'de'
  FROM inserted_playbook ipb
 WHERE NOT EXISTS (
       SELECT 1 FROM playbook_version v WHERE v.playbook_id = ipb.id AND v.version = 1
 );

-- 3.3) Playbook Agent anlegen & pflegen ---------------------------------------------------
WITH ws_owner AS (
    SELECT w.id AS workspace_id,
           COALESCE(
             (SELECT user_id FROM workspace_member
                WHERE workspace_id = w.id AND role = 'admin'
                ORDER BY joined_at ASC, user_id ASC LIMIT 1),
             (SELECT user_id FROM workspace_member
                WHERE workspace_id = w.id
                ORDER BY joined_at ASC, user_id ASC LIMIT 1)
           ) AS owner_id
      FROM workspace w
),
inserted_playbook AS (
    INSERT INTO playbook (workspace_id, owner_id, name, type, tags, triggers)
    SELECT wo.workspace_id, wo.owner_id, 'Agent anlegen & pflegen', 'workflow',
           ARRAY['agent', 'crud', 'agent-building']::text[], 'agent anlegen, agent konfigurieren, agent bearbeiten, tool policy, agent kopieren'
      FROM ws_owner wo
     WHERE wo.owner_id IS NOT NULL
       AND NOT EXISTS (
         SELECT 1 FROM playbook p
          WHERE p.workspace_id = wo.workspace_id AND p.name = 'Agent anlegen & pflegen'
       )
    RETURNING id, owner_id
)
INSERT INTO playbook_version (playbook_id, version, content, status, created_by, locale)
SELECT ipb.id, 1, $w2bpb3${"description": "Einen Agenten konfigurieren: Persona + Template verdrahten, Tool-Policy setzen, kopieren.", "body": "[{\"id\": \"pb-agent-h-zweck\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Zweck\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-p-zweck\", \"type\": \"paragraph\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Dieses Playbook fuehrt dich durch das Anlegen und Pflegen eines Agenten in Who2Be. Ein Agent ist die ausfuehrbare Konfiguration: genau eine Persona, genau ein System-Prompt-Template und eine tool_policy, die festlegt, welche MCP-Werkzeuge der Agent nutzen darf. Du arbeitest in vier Phasen — Verstehen, Vorschlag, Schreiben, Hand-Off.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-h-remap\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Wichtig: Template waehlen statt Template bauen\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-p-remap\", \"type\": \"paragraph\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"In Who2Be gibt es \", \"styles\": {}}, {\"type\": \"text\", \"text\": \"kein MCP-Werkzeug, das System-Prompt-Templates erzeugt\", \"styles\": {\"bold\": true}}, {\"type\": \"text\", \"text\": \". Der frueher noetige Bootstrap-Block lebt heute im Template selbst und wird serverseitig beim Rendern aus Platzhaltern befuellt (Persona-Felder, Werkzeug-Liste, Playbook-Katalog, Datum). Du waehlst beim Anlegen eines Agenten daher eine der bestehenden Default-Templates ueber ihre system_prompt_template_id aus — du schreibst kein Template-Body. Wenn der Nutzer ein eigenes Template braucht, ist das ein Schritt in der Web-Oberflaeche, nicht ueber MCP.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-h-modus\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Modus erkennen\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-modus-create\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Create: \", \"styles\": {\"bold\": true}}, {\"type\": \"text\", \"text\": \"ein neuer Agent wird gebraucht — create_agent verdrahtet Persona, Template und tool_policy.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-modus-update\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Update: \", \"styles\": {\"bold\": true}}, {\"type\": \"text\", \"text\": \"ein bestehender Agent bekommt eine neue Persona, ein anderes Template, eine geaenderte tool_policy oder einen neuen Status — update_agent aendert die Konfig in-place (Agenten haben keine Versionshistorie).\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-modus-copy\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Copy: \", \"styles\": {\"bold\": true}}, {\"type\": \"text\", \"text\": \"ein aktivierbarer Agent dient als Vorlage fuer eine Variante — copy_agent dupliziert Persona, Template, Beschreibung und Status.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-modus-retire\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Deaktivieren / Reaktivieren: \", \"styles\": {\"bold\": true}}, {\"type\": \"text\", \"text\": \"ein Agent soll aus dem Betrieb genommen oder zurueckgeholt werden — das ist ein update_agent mit status=disabled bzw. status=enabled, kein transition_*-Aufruf.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-h-create\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Create-Modus\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-h-create-p1\", \"type\": \"heading\", \"props\": {\"level\": 3, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Phase 1 — Verstehen\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-create-p1-1\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Persona muss existieren und eine aktive Version haben. \", \"styles\": {\"bold\": true}}, {\"type\": \"text\", \"text\": \"Pruefe mit get_persona(identifier). Fehlt sie, lege sie zuerst ueber das Playbook „Persona anlegen & pflegen“ an und kehre dann hierher zurueck. Ohne aktive Persona-Version laesst sich der Agent nicht aktivieren.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-create-p1-2\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Agent-Namen klaeren — kurz und eindeutig, das ist der Anzeigename in der Agenten-Liste.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-create-p1-3\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Template auswaehlen: Welche der bestehenden Default-Templates passt zur Aufgabe? Notiere ihre system_prompt_template_id. (Du erzeugst kein Template — du waehlst eines aus.)\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-create-p1-4\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Rechte klaeren: Soll der Agent nur lesen oder auch schreiben? Daraus ergibt sich die tool_policy (siehe Sektion „tool_policy verstehen“).\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-h-create-p2\", \"type\": \"heading\", \"props\": {\"level\": 3, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Phase 2 — Vorschlag\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-create-p2-1\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Stelle dem Nutzer die geplante Konfiguration vor: Name, gewaehlte Persona, gewaehltes Template und die tool_policy (Lese-Scopes und Schreib-Capabilities im Klartext).\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-create-p2-2\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Erklaere die Folgen: Mit aktiver Persona und gesetztem Template ist der Agent aktivierbar (activatable) und kann sofort als enabled angelegt werden. Hole die Bestaetigung ein.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-h-create-p3\", \"type\": \"heading\", \"props\": {\"level\": 3, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Phase 3 — Schreiben\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-p-create-p3\", \"type\": \"paragraph\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Rufe create_agent mit diesen Feldern auf:\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-create-p3-1\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"name\", \"styles\": {\"code\": true}}, {\"type\": \"text\", \"text\": \" — der geklaerte Agent-Name.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-create-p3-2\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"persona_id\", \"styles\": {\"code\": true}}, {\"type\": \"text\", \"text\": \" — die ID der Persona mit aktiver Version.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-create-p3-3\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"system_prompt_template_id\", \"styles\": {\"code\": true}}, {\"type\": \"text\", \"text\": \" — die ID der gewaehlten Default-Template.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-create-p3-4\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"tool_policy\", \"styles\": {\"code\": true}}, {\"type\": \"text\", \"text\": \" — die abgestimmten Lese-Scopes und Schreib-Capabilities. Ohne Angabe gilt der Default: alles lesen, nichts schreiben.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-create-p3-5\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"status\", \"styles\": {\"code\": true}}, {\"type\": \"text\", \"text\": \" — Default ist disabled. Setze enabled nur, wenn der Agent aktivierbar ist (Persona + Template gesetzt UND Persona hat eine aktive Version); sonst antwortet der Server mit 409.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-h-create-p4\", \"type\": \"heading\", \"props\": {\"level\": 3, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Phase 4 — Hand-Off\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-create-p4-1\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Pruefe das Ergebnis mit fetch_agent(agent_id): Der gerenderte System-Prompt darf keine ungefuellten Platzhalter enthalten (unresolved_placeholders ist leer).\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-create-p4-2\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Melde dem Nutzer Name, ID und Status zurueck und nenne offene Luecken (missing), falls der Agent noch nicht aktivierbar ist.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-h-update\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Update-Modus\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-update-1\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Verstehen: fetch_agent(agent_id) liest den aktuellen Stand (Persona, Template, tool_policy, Status, missing).\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-update-2\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Vorschlag: Zeige genau das Delta — welches Feld sich aendert und warum. Nur angegebene Felder werden ueberschrieben; ein ausgelassenes tool_policy bleibt unveraendert.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-update-3\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Schreiben: update_agent mit den geaenderten Feldern (name, description, persona_id, system_prompt_template_id, tool_policy, status). Beachte: Ein gesetztes \", \"styles\": {}}, {\"type\": \"text\", \"text\": \"tool_policy ersetzt die Policy vollstaendig\", \"styles\": {\"bold\": true}}, {\"type\": \"text\", \"text\": \" (Replace-Semantik) — uebernimm die bestehenden Werte mit, die du behalten willst.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-update-4\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Hand-Off: Erneut fetch_agent zum Verifizieren des Renders. Wenn aktive Sitzungen laufen, weise darauf hin, dass eine neue Sitzung noetig ist, damit die geaenderte Konfiguration greift.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-h-copy\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Copy-Modus\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-copy-1\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Nur aktivierbare Agenten lassen sich kopieren — eine unvollstaendige Huelle (Persona oder Template fehlt) ist nicht kopierbar. Pruefe das vorab mit fetch_agent.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-copy-2\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Rufe copy_agent mit der Quell-ID auf. \", \"styles\": {}}, {\"type\": \"text\", \"text\": \"name\", \"styles\": {\"code\": true}}, {\"type\": \"text\", \"text\": \" ist optional — ohne Angabe leitet der Server „<Name> (Kopie)“ ab. Die Kopie uebernimmt Persona, Template, Beschreibung und Status der Quelle.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-copy-3\", \"type\": \"numberedListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Passe die Kopie anschliessend per update_agent an (z. B. andere Persona oder engere tool_policy) und verifiziere mit fetch_agent.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-h-disable\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Deaktivieren & Reaktivieren\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-p-disable\", \"type\": \"paragraph\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Agenten haben keinen Versions-Lebenszyklus wie Persona, Playbook oder Resource — es gibt nur enabled und disabled. Beides setzt du ueber update_agent(status=...). Ein disabled Agent ist in der Liste gefiltert und sein Render-Endpoint antwortet mit 409. Vor dem Deaktivieren: Pruefe, ob der Agent noch aktiv genutzt wird, und warne den Nutzer entsprechend. Reaktivieren ist nur moeglich, solange der Agent aktivierbar bleibt (Persona mit aktiver Version + Template).\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-h-policy\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"tool_policy verstehen\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-p-policy\", \"type\": \"paragraph\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Die tool_policy legt fest, welche MCP-Werkzeuge der Agent sieht und nutzen darf. Default ist „alles lesen, nichts schreiben“ — ein frischer Agent darf den ganzen Workspace lesen, aber nichts veraendern, bis es freigeschaltet wird.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-policy-reads\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Lese-Scopes: \", \"styles\": {\"bold\": true}}, {\"type\": \"text\", \"text\": \"playbook_read und resource_read sind dreistufig — all (ganzer Workspace), assigned (nur die der eigenen Persona zugewiesenen) oder none (Werkzeug ausgeblendet). persona_read und agent_read sind einfache An/Aus-Schalter.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-policy-writes\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Schreib-Capabilities: \", \"styles\": {\"bold\": true}}, {\"type\": \"text\", \"text\": \"persona_write, playbook_write, resource_write und agent_write schalten je die Schreib-Tools der Domain frei (Draft anlegen/aendern, Verknuepfungen setzen). Default jeweils aus.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-policy-promote\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"promote_retire: \", \"styles\": {\"bold\": true}}, {\"type\": \"text\", \"text\": \"noetig, um eine Version auf active oder inactive zu schalten (veroeffentlichen/zurueckziehen). Nach draft/review genuegt die jeweilige Schreib-Capability; das Promoten/Retiren ist die zusaetzliche Stufe.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-policy-escalation\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Keine Rechte-Eskalation: \", \"styles\": {\"bold\": true}}, {\"type\": \"text\", \"text\": \"Legst du selbst als Agent via agent_write einen anderen Agenten an, darf dessen Policy nicht mehr gewaehren als deine eigene. Die tool_policy ist nur die Tool-Sichtbarkeit — die eigentliche Autorisierung (editor fuer Schreiben, admin fuer Promote/Retire) bleibt serverseitig.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-h-activatable\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Aktivierbarkeit (activatable)\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-act-1\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Ein Agent ist activatable, wenn Persona UND Template gesetzt sind UND die Persona eine aktive Version hat. Nur dann darf er enabled oder kopiert werden.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-act-2\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Das Feld missing zeigt die Luecken in stabiler Reihenfolge: persona, template, persona_active. Eine leere Liste heisst aktivierbar.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-act-3\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Solange Persona oder Template fehlt, ist der Agent eine Huelle (is_shell): nicht renderbar und nicht kopierbar. Das Anlegen einer Huelle ist erlaubt und wird spaeter per update_agent vervollstaendigt.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-h-tools\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Werkzeuge & Operationen\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-tools-read\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Lesen: \", \"styles\": {\"bold\": true}}, {\"type\": \"text\", \"text\": \"get_persona (Persona + aktive Version pruefen), fetch_agent (aktueller Stand + gerenderter Prompt + missing), list_playbooks zur Orientierung.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-tools-write\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Schreiben: \", \"styles\": {\"bold\": true}}, {\"type\": \"text\", \"text\": \"create_agent (anlegen), update_agent (Konfig in-place, inkl. Status), copy_agent (duplizieren). Alles braucht die Schreib-Capability agent_write; serverseitig gilt editor.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-tools-forbidden\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Nicht verfuegbar: \", \"styles\": {\"bold\": true}}, {\"type\": \"text\", \"text\": \"Template-Erzeugung (keine via MCP), Agent-Loeschen (kein MCP-Delete, ADR-0030) und transition_*-Aufrufe auf Agenten (Agenten haben keine Versionen).\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-h-anti\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Anti-Patterns\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-anti-1\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Agent mit status=enabled anlegen, obwohl er nicht aktivierbar ist — der Server lehnt mit 409 ab. Erst Persona (aktiv) + Template sicherstellen.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-anti-2\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Persona ohne aktive Version verdrahten — der Agent bleibt nicht aktivierbar (missing fuehrt persona_active).\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-anti-3\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"tool_policy beim Update nur teilweise senden in der Annahme, die fehlenden Felder blieben erhalten — ein gesetztes tool_policy ersetzt die ganze Policy. Bestehende Werte mit uebergeben.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-anti-4\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Schreib-Capabilities grosszuegiger setzen, als der Agent fuer seine Aufgabe braucht — vergib das Minimum (Least Privilege) und niemals mehr, als du selbst hast.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-anti-5\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Den Render nach create_agent oder update_agent nicht mit fetch_agent verifizieren — ungefuellte Platzhalter blieben sonst unbemerkt.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-h-notes\", \"type\": \"heading\", \"props\": {\"level\": 2, \"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Notes\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-notes-1\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Reihenfolge zaehlt: erst Persona (mit aktiver Version), dann Template waehlen, dann Agent anlegen. Die natuerliche Abhaengigkeit ist Persona → Template → Agent.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-notes-2\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Keine Versions-Disziplin auf dem Agenten selbst: Aenderungen sind reine Konfig-Updates ohne Versions-Bump. Inhaltliche Versionierung lebt auf Persona, Playbook und Resource.\", \"styles\": {}}], \"children\": []}, {\"id\": \"pb-agent-li-notes-3\", \"type\": \"bulletListItem\", \"props\": {\"textColor\": \"default\", \"backgroundColor\": \"default\", \"textAlignment\": \"left\"}, \"content\": [{\"type\": \"text\", \"text\": \"Der Bootstrap-Loop (Persona laden, Trigger pruefen, Playbook folgen) steckt im Template und wird beim Rendern aus Platzhaltern befuellt — du musst ihn nicht von Hand in den Prompt schreiben.\", \"styles\": {}}], \"children\": []}]", "type": "workflow", "tags": ["agent", "crud", "agent-building"], "triggers": "agent anlegen, agent konfigurieren, agent bearbeiten, tool policy, agent kopieren"}$w2bpb3$::jsonb, 'active', ipb.owner_id, 'de'
  FROM inserted_playbook ipb
 WHERE NOT EXISTS (
       SELECT 1 FROM playbook_version v WHERE v.playbook_id = ipb.id AND v.version = 1
