-- 3.4) Playbook Konsistenz- & Drift-Check ---------------------------------------------------
WITH ws_owner AS (
    SELECT w.id AS workspace_id,
           COALESCE(
             (SELECT user_id FROM workspace_member
                WHERE workspace_id = w.id AND role = 'admin'
                ORDER BY joined_at ASC, user_id ASC LIMIT 1),
             (SELECT user_id FROM workspace_member
                WHERE workspace_id = w.id
                ORDER BY joined_at ASC, user_id ASC LIMIT 1)
           ) AS owner_id
      FROM workspace w
),
inserted_playbook AS (
    INSERT INTO playbook (workspace_id, owner_id, name, type, tags, triggers)
    SELECT wo.workspace_id, wo.owner_id, 'Konsistenz- & Drift-Check', 'checklist',
           ARRAY['konsistenz', 'qa', 'agent-building']::text[], 'konsistenz, drift, pruefen, aktivierbar, activatable, qualitaetscheck'
      FROM ws_owner wo
     WHERE wo.owner_id IS NOT NULL
       AND NOT EXISTS (
         SELECT 1 FROM playbook p
          WHERE p.workspace_id = wo.workspace_id AND p.name = 'Konsistenz- & Drift-Check'
       )
    RETURNING id, owner_id
)
